define(["jquery"],function($){class Html5Adapter{constructor(root,config){this.root=root;this.config=config;this.video=root.querySelector('[data-region="html5-player"]');this.handlers={};this.lastTime=0}initialise(){if(!this.video){return Promise.reject(new Error("HTML5 player element is missing"))}if(this.config.disabledownload){this.video.setAttribute("controlsList","nodownload")}if(this.config.disablepip){this.video.disablePictureInPicture=true}if(this.config.disablecontextmenu){this.video.addEventListener("contextmenu",event=>event.preventDefault())}this.video.addEventListener("play",()=>this.emit("play"));this.video.addEventListener("pause",()=>this.emit("pause"));this.video.addEventListener("ended",()=>this.emit("ended"));this.video.addEventListener("timeupdate",()=>{const current=this.getCurrentTime();this.emit("timeupdate",current);this.lastTime=current});this.video.addEventListener("seeking",()=>this.emit("seek",this.getCurrentTime(),this.lastTime));this.video.addEventListener("ratechange",()=>{const maximum=Number(this.config.maxplaybackrate||0);if(maximum>0&&this.video.playbackRate>maximum){this.video.playbackRate=maximum}this.emit("ratechange",this.getPlaybackRate())});return new Promise(resolve=>{if(this.video.readyState>=1){resolve(this)}else{this.video.addEventListener("loadedmetadata",()=>resolve(this),{once:true})}})}play(){return this.video.play()}pause(){this.video.pause()}getCurrentTime(){return Number(this.video.currentTime||0)}getDuration(){return Number.isFinite(this.video.duration)?Number(this.video.duration):0}getPlaybackRate(){return Number(this.video.playbackRate||1)}seek(position){this.video.currentTime=Math.max(0,Math.min(this.getDuration(),Number(position)))}onPlay(handler){this.on("play",handler)}onPause(handler){this.on("pause",handler)}onTimeUpdate(handler){this.on("timeupdate",handler)}onSeek(handler){this.on("seek",handler)}onEnded(handler){this.on("ended",handler)}onRateChange(handler){this.on("ratechange",handler)}on(name,handler){this.handlers[name]=this.handlers[name]||[];this.handlers[name].push(handler)}emit(name,...args){(this.handlers[name]||[]).forEach(handler=>handler(...args))}}return Html5Adapter});